import logging
import telnetlib
import re
from taf.internal.managedobject import ManagedObject
from .exception import TimeoutErrorWithData

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ManagedTelnetConnection(ManagedObject):
    """
    ManagedObject interface for TelnetConnection.

    - Create TelnetConnection.
    - Configure the delegate in constructor.
    - Map setup()/teardown() to open()/close().
    - Log setup/teardown.
    """

    def __init__(
            self,
            host,
            port,
            timeout=5,
            telnet_connection=None,
            **kwargs):
        """
        Create an TelnetConnection.

        :param str host: host or IP address
        :param int port: port
        :param int timeout: (optional) timeout value in seconds, default is '5'
        """
        super(ManagedTelnetConnection, self).__init__(**kwargs)
        self._host = host
        self._port = port
        self.timeout = timeout
        if telnet_connection is None:
            telnet_connection = telnetlib.Telnet()
        self._telnet_connection = telnet_connection

    @property
    def telnet_connection(self):
        """
        Return the telnetlib.Telnet() object used internally

        :return telnetlib.Telnet
        """
        return self._telnet_connection

    @property
    def host(self):
        return self._host

    @property
    def port(self):
        if callable(self._port):
            return self._port()
        else:
            return self._port

    def __getattr__(self, name):
        return getattr(self._telnet_connection, name)

    def _setup(self):
        logger.debug("connecting to {host!r}:{port!r}".format(
            host=self.host,
            port=self.port))
        self.open(host=self.host, port=self.port, timeout=self.timeout)

    def _teardown(self):
        logger.debug("disconnecting from {host!r}:{port!r}".format(
            host=self.host,
            port=self.port))
        self.close()

    def _read_until_prompt(self, prompt, timeout):
        re_compiled = [re.compile(b'^\r?' + prompt, re.MULTILINE)]
        output = self.telnet_connection.expect(re_compiled, timeout=timeout)
        if output[0] != -1 or output[2].endswith(prompt):
            return output[2]
        else:
            raise TimeoutErrorWithData(data=output[2])


class ManagedCliTelnetConnection(ManagedTelnetConnection):
    def __init__(
            self,
            prompt,
            set_prompt_command=None,
            **kwargs):
        """
        Create an TelnetConnection with CLI support.

        :param bytes prompt: telnet shell prompt's regex pattern
        :param str set_prompt_command: (optional) command required to set prompt post login
        """
        super(ManagedCliTelnetConnection, self).__init__(**kwargs)
        self._set_prompt_command = set_prompt_command
        self.prompt = prompt

    @property
    def is_connected(self):
        """
        Checks if telnet connection is still active/responding or not

        :return Boolean
        """
        try:
            flushed_output = self.read_very_eager()
            if flushed_output != b'':
                logger.debug("Flushed Output: {}".format(flushed_output))
            self.write(b"\n")
            self._read_until_prompt(self.prompt, timeout=2)
            return True
        except (TimeoutErrorWithData, EOFError):
            return False

    def _setup(self):
        super(ManagedCliTelnetConnection, self)._setup()
        if self._set_prompt_command:
            self.write(self._set_prompt_command + b"\n")
        self._read_until_prompt(self.prompt, timeout=2)

    def execute(self, command, timeout=None):
        """
        Execute given command in telnet session.

        :param bytes command: command need to be executed
        :param float timeout: (optional) timeout value, must be greater than 0
        :return: bytes, output observed post command execution
        """
        flushed_output = self.read_very_eager()
        if flushed_output != b'':
            logger.debug("Flushed Output: {}".format(flushed_output))
        logger.debug("Executing telnet command: {command}".format(command=command))
        self.write(command + b"\n")
        command_output = self._read_until_prompt(
            self.prompt,
            timeout=timeout or self.timeout)[:-(len(self.prompt))]
        logger.debug(
            "Received output for prompt '{prompt}'"
            " and wait time '{timeout}' seconds: {output}".format(
                prompt=self.prompt,
                timeout=timeout or self.timeout,
                output=command_output))
        return command_output.strip()


class ManagedLoginTelnetConnection(ManagedTelnetConnection):
    def __init__(
            self,
            login_prompt=None,
            user=None,
            password_prompt=None,
            password=None,
            **kwargs):
        """
        Create an TelnetConnection with Login Support.

        :param str login_prompt: login prompt's regex pattern if authentication required
        :param str user: user if authentication required
        :param str password_prompt: password prompt's regex pattern if authentication required
        :param str password: password if authentication required
        """
        super(ManagedLoginTelnetConnection, self).__init__(**kwargs)
        self._login_prompt = login_prompt
        self._user = user
        self._password_prompt = password_prompt
        self._password = password

    def _setup(self):
        super(ManagedLoginTelnetConnection, self)._setup()
        for (prompt, credential) in [(self._login_prompt, self._user),
                                     (self._password_prompt, self._password)]:
            if prompt:
                logger.debug("Waiting for '{prompt}' prompt and sending '{credential}'".format(
                    prompt=prompt,
                    credential=credential))
                logger.debug("Received response: {output}".format(
                    output=self._read_until_prompt(prompt, timeout=self.timeout)))
                self.write(credential + b'\n')


class ManagedLoginCliTelnetConnection(ManagedCliTelnetConnection, ManagedLoginTelnetConnection):
    """
    Create an TelnetConnection with Login and Cli Support.
    """
    pass
